import {supabase,$,node,read,session,invoke,fields,shipping,status} from './commerce-client.js';
let products=[]; let requestKey;
function render(){const list=$('#products');list.replaceChildren();const filtered=products.filter(p=>!$('#category').value||p.category_slug===$('#category').value);if(!filtered.length){list.append(node('p','Products are being reviewed. The catalogue will appear here when FI has confirmed the details.','empty'));return;}for(const p of filtered){const card=node('article',null,'card');if(p.image_url){const img=node('img');img.src=p.image_url;img.alt=p.title;img.loading='lazy';card.append(img);}else card.append(node('div','Product photo pending','placeholder'));card.append(node('h2',p.title),node('p',p.description),node('p','Inclusive AUD price confirmed for your delivery address.','muted'));if(p.image_kind==='illustration')card.append(node('small','Illustration ; refer to specifications for the supplied product.'));const specs=node('dl');for(const [key,value] of Object.entries(p.specifications)){specs.append(node('dt',key),node('dd',String(value)));}card.append(specs);const button=node('button','Get inclusive quote');button.onclick=async()=>{try{await session(true);requestKey=crypto.randomUUID();$('#order-form').reset();$('#order-form').elements.product_id.value=p.id;$('#product-title').textContent=p.title;$('#dialog-status').textContent='';$('#order-dialog').showModal();}catch(error){status(error.message,true);}};card.append(button);list.append(card);}}
$('#close-dialog').onclick=()=>$('#order-dialog').close();$('#category').onchange=render;
$('#order-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const button=form.querySelector('button[type=submit]');button.disabled=true;$('#dialog-status').textContent='Saving your request…';try{const values=fields(form);const result=await invoke('create_order',{request_key:requestKey,items:[{product_id:values.product_id,quantity:Number(values.quantity)}],phone:values.phone,shipping_address:shipping(values),delivery_notes:values.delivery_notes,accepted_terms:values.accepted_terms==='on'});location.assign(`orders.html?order=${result.id}`);}catch(error){$('#dialog-status').textContent=error.message;}finally{button.disabled=false;}};
try{const categories=await read('fi_shop_categories');for(const c of categories.sort((a,b)=>a.sort_order-b.sort_order)){const option=node('option',c.name);option.value=c.slug;$('#category').append(option);}const {data,error}=await supabase.from('fi_shop_products').select('*').eq('status','published').order('created_at',{ascending:false});if(error)throw error;products=data;render();}catch(error){status('The catalogue could not load. Please try again later.',true);}
